L82: export interface CommandResult {
L83:   exitCode: number
L84:   stdout: string
L85:   stderr: string
L86: }
L87: 
L88: /**
L89:  * Runs the completion check command in a real system shell (`/bin/sh -c`).
L90:  *
L91:  * The previous implementation used opencode's built-in Bun shell via
L92:  * `` $`${command}` ``. Bun interpolates the whole command string as a single
L93:  * quoted argument and resolves binaries against its own restricted PATH, which
L94:  * breaks commands such as `docker compose run ...` with errors like
L95:  * "Bun: command not found: docker" even though `docker` is on the user's PATH.
L96:  *
L97:  * Using `child_process.exec` runs the command through the real `/bin/sh`, so
L98:  * the command line is parsed normally and binaries are resolved against the
L99:  * inherited PATH exactly like in a normal terminal (including `/sbin`,
L100:  * `/usr/sbin`, etc.).
L101:  */
L102: export async function executeCommand(command: string, cwd: string): Promise<CommandResult> {
L103:   return new Promise((resolve) => {
L104:     exec(command, { cwd, maxBuffer: 10 * 1024 * 1024 }, (error, stdout, stderr) => {
L105:       let exitCode = 0
L106:       if (error) {
L107:         exitCode = typeof error.code === 'number' ? error.code : 1
L108:       }
L109:       resolve({
L110:         exitCode,
L111:         stdout: stdout.toString(),
L112:         stderr: stderr.toString(),
L113:       })
L114:     })
L115:   })
L116: }
L117: 
L118: export function buildFailureMessage(result: CommandResult): string {
L119:   let message = 'you are not yet finished:\n'
L120:   if (result.stdout) {
L121:     message += `\nstdout:\n${result.stdout}`
L122:   }
L123:   if (result.stderr) {
L124:     message += `\nstderr:\n${result.stderr}`
L125:   }
L126:   if (!result.stdout && !result.stderr) {
L127:     message += `\nCommand exited with code ${result.exitCode}`
L128:   }
L129:   return message

import { Plugin } from '@opencode/plugin'
import { CompletionCheckCommandPlugin } from './completion-check-command.js'
import { CompletionCheckCommandSetup } from './v2.js'

export default {
  ...Plugin.define({
    id: 'opencode-completion-check-command',
    setup: CompletionCheckCommandSetup,
  }),
  server: CompletionCheckCommandPlugin,
}
